#ifndef  _ESP32S3_H
#define  _ESP32S3_H

#include "esp32s3_parms.H"
#include "systemc.h"
#include "ac_module.H"
#include "ac_utils.H"
#include "esp32s3_arch.H"
#include "esp32s3_isa.H"
#include "esp32s3_syscall.H"


class esp32s3: public ac_module, public esp32s3_arch {
private:
  typedef struct {
    uint8_t op;
    uint8_t op1;
    uint8_t r;
    uint8_t s;
    uint8_t t;
    uint8_t op2;
  } T_Type_RRR;

  typedef struct {
    uint8_t op;
    int8_t imm8;
    uint8_t s;
    uint8_t t;
    uint8_t pad1;
  } T_Type_RRI8;

  typedef struct {
    uint8_t op;
    uint8_t t;
    int16_t imm16;
    uint8_t pad2;
  } T_Type_RI16;

  typedef struct {
    uint8_t op;
    uint8_t disp;
    uint8_t s;
    uint8_t t;
    uint8_t pad3;
  } T_Type_L32I;

  typedef struct {
    uint8_t op;
    int16_t bdisp;
    uint8_t s;
    uint8_t t;
    uint8_t pad4;
  } T_Type_Branch;

  typedef struct {
    uint8_t op;
    int32_t target;
    uint8_t pad5;
  } T_Type_Jump;

  typedef struct {
    uint8_t op;
    uint8_t ldisp;
    uint8_t s;
    uint16_t pad6;
  } T_Type_Loop;

  typedef struct {
    uint8_t op;
    uint8_t qr;
    uint8_t qs;
    uint8_t qt;
    uint8_t mode;
    uint8_t pad8;
  } T_Type_PIE;

  typedef struct {
    uint8_t op;
    uint32_t pad7;
  } T_Type_Halt;

  typedef struct {
    bool valid;
    void* end_rot;
    unsigned id;
    union {
      T_Type_RRR F_Type_RRR;
      T_Type_RRI8 F_Type_RRI8;
      T_Type_RI16 F_Type_RI16;
      T_Type_L32I F_Type_L32I;
      T_Type_Branch F_Type_Branch;
      T_Type_Jump F_Type_Jump;
      T_Type_Loop F_Type_Loop;
      T_Type_PIE F_Type_PIE;
      T_Type_Halt F_Type_Halt;
    };
  } DecCacheItem ;

public:

  bool has_delayed_load;
  char* delayed_load_program;
  esp32s3_parms::esp32s3_isa ISA;
  //!Address of Interpretation Routines.
  void** IntRoutine;

  DecCacheItem* DEC_CACHE;
  DecCacheItem* instr_dec;
  bool start_up;

  //!Dispatch Method.
  inline __attribute__((always_inline)) void* dispatch();

  //!Behavior execution method.
  void behavior();

  SC_HAS_PROCESS( esp32s3 );

  sc_event wake;

  //!Constructor.
  esp32s3( sc_module_name name_ ): ac_module(name_), esp32s3_arch(), ISA(*this) {
    SC_THREAD( behavior );
    sensitive << wake;
    has_delayed_load = false; 
    start_up=1;
    ac_id.write(globalId++);
  }

  void init_dec_cache() {
    DEC_CACHE = (DecCacheItem*) calloc(sizeof(DecCacheItem), (dec_cache_size / 4));
  }

  unsigned get_ac_pc();

  void set_ac_pc( unsigned int value );

  virtual void PrintStat();

  void init(int ac, char* av[]);

  void init();

  void set_prog_args();

  void load(char* program);

  void delayed_load(char* program);

  void stop(int status = 0);

  virtual ~esp32s3() {};

};
#endif  //_ESP32S3_H

